        Oil.OilAltCp(c, alt, 66);
        Oil.OilEnd(c, at);
        emon.Testport.AssertEq(Oil.OilWordNext(c, at, w), emon.Port.CellsLen(c), "walk past symbol text and alternatives");
    }
    [Xunit.Fact]
    public static void TestObservedIdentityHashesCanonicalUtf8() {
        emon.Port.Cells cps = emon.Port.NewCells();
        emon.Testport.AssertEq64(Oil.OilObsHash(cps, 0, 0), -3750763034362895579, "FNV offset basis");
        emon.Port.CellsPush(cps, 104);
        emon.Port.CellsPush(cps, 101);
        emon.Port.CellsPush(cps, 108);
        emon.Port.CellsPush(cps, 108);
        emon.Port.CellsPush(cps, 111);
        emon.Testport.AssertEq64(Oil.OilObsHash(cps, 0, 5), -6615550055289275125, "ASCII hello");
        emon.Port.CellsPush(cps, 233);
        emon.Port.CellsPush(cps, 128512);
        emon.Testport.AssertEq64(Oil.OilObsHash(cps, 5, 2), 5970206017523824492, "accent plus supplementary code point");
    }
    [Xunit.Fact]
    public static void TestWordAlternativesDoNotDisplaceTextOrSymbols() {
        emon.Port.Cells c = emon.Port.NewCells();
